INSERT INTO "search_executions" ("exec_id", "slug", "parameter_id", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session", "identity_code", "icf_code", "needs_code", "medical_code") VALUES (199, NULL, 9, NULL, 'EN', NULL, NULL, NULL, 'eutils.ncbi.nlm.nih.gov PubMed: wheelchair AND (doorway OR "door width" OR "corridor width") AND (qualitative OR interview OR "focus group" OR participatory OR "lived experience" OR barriers)', NULL, 'pubmed', 'scoping', NULL, 4, 4, 0, 'partial', NULL, NULL, 0, 'session_2026-11-06-pipeline-batch', '2026-11-06 03:07', 'Second shape for the door and corridor width search (exec 198 returned one hit). Four hits: 18002971 (already seen at exec 198, robotics overview), 29130752 (D''Souza et al. 2019, 48 wheeled mobility users rating bus mock-up layouts; a bus interior, not a building door), 29500093 (mammography in women with cerebral palsy, off topic), 41068262 (evacuation simulation model, off topic). Nothing staged: none states a door or corridor width measured on or reported by disabled people. Widening the barrier terms returned off-topic surveys; the narrower shape in the next row found on-topic work.', 0, 'Written AFTER the adversarial critic reported 4 hits for this shape, so NOT independent of the result: expected 3-8 hits, mostly environmental-barrier surveys, with 0-2 giving a door or aperture width measured on disabled participants.', 'incidental', NULL, NULL, '2026-11-06 03:07', 'session_2026-11-06-pipeline-batch', NULL, NULL, NULL, NULL);
INSERT INTO "search_executions" ("exec_id", "slug", "parameter_id", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session", "identity_code", "icf_code", "needs_code", "medical_code") VALUES (200, NULL, 9, NULL, 'EN', NULL, NULL, NULL, 'eutils.ncbi.nlm.nih.gov PubMed: wheelchair AND doorway AND width', NULL, 'pubmed', 'scoping', NULL, 5, 5, 0, 'partial', NULL, NULL, 0, 'session_2026-11-06-pipeline-batch', '2026-11-06 03:07', 'Five hits, three on topic for parameter 9 and staged as candidates: 19212090 (Higuchi et al. 2009, tetraplegic wheelchair users and controls judging whether a doorway width is passable), 22317349 (Paquet, Joseph and D''Souza 2012, anthropometric re-sampling method illustrated on door width and clear floor space width), 9661706 (Savelsbergh et al. 1998, children with cerebral palsy locomoting through apertures of different width). Two off topic: 2717384 (a wheelchair narrower, 1989), 15677036 (taxi entrances). Nothing admitted: abstracts only, no door width figure in any abstract, full text not sought. This narrower shape exposed what exec 198 missed, which makes exec 198 a query-shape failure and not an absence.', 0, 'Written AFTER the adversarial critic reported 5 hits for this shape, so NOT independent of the result: expected 3-8 hits, 1-3 of them measuring or testing a doorway width with wheelchair users.', 'incidental', NULL, NULL, '2026-11-06 03:07', 'session_2026-11-06-pipeline-batch', NULL, NULL, NULL, NULL);
UPDATE "search_executions" SET "findings_note" = 'Four hits, three on topic: Koontz 2010 (PMID 20434614, T1 case series, n=223, minimum passageway widths for L-turn, 360-degree turn and U-turn); Steinfeld 2010 (PMID 20402047, international comparison of anthropometry and standards); King 2011 (PMID 21657823, scooter three-point-turn areas). One off topic (PMID 36038463, a Delphi study of the word wheelchair-bound). None admitted: Europe PMC reports no open full text for Koontz or Steinfeld (isOpenAccess N, inPMC N), and the abstracts state no dimension, so an admission would add no extractable figure. Koontz and King DOIs are held as RETIRED stash rows (REF-00784, REF-00972): a re-admission cross-files to those ids. Query shape: well-formed; PubMed parsed turning space as turning AND space. Count 4 is below the prior floor of 5; the shortfall reads as an indexing fact (the main US report is not in PubMed), not a query-shape failure. || CORRECTED 2026-11-06: Harm flag raised after the adversarial pass. The efetch abstract of PMID 20434614 (retrieval-log/session_2026-11-06-pipeline-batch/edb5140e7b6d9611.xml) states: Between 10% and 100% of users would not be able to maneuver in spaces that meet current Accessibility Guidelines for Buildings and Facilities specifications. Extraction 183 (ADA 304.3.1, 1525 mm) files the guideline figure that finding concerns; its contested flag stays 0, because no writer amends it and the statement is an abstract-level hypothesis (R15), not a read. The Europe PMC open-access check named above is persisted: 198b3da3fb3d7b6a.json (PMID 20434614) and c4c1f76df9877588.json (PMID 20402047). The tier guess of candidate 150 is corrected to 3.', "harm_finding" = 1, "updated_at" = '2026-11-06 03:07' WHERE "exec_id" = 197;
UPDATE "search_executions" SET "findings_note" = 'ZERO-YIELD for Co-1: the one hit (PMID 18002971, Cooper et al. 2007, robotics for personal mobility) reports focus-group participants naming doorways as a barrier but is an engineering overview, not a participatory dimension study; not a Co-1 source for a door or corridor width and not admitted. R14 diagnosis: QUERY-SHAPE FAILURE, not genuine absence. Three AND-ed concept groups; PubMed does not index participatory design-standard work from disabled persons organisations, which publishes as grey reports. A Co-1 retrieval for door and corridor widths is NOT done by this batch and stays open. || CORRECTED 2026-11-06: The R14 label is corrected and one reason withdrawn. This was a QUERY-SHAPE failure; the reason given above, that PubMed does not index participatory design-standard work, is withdrawn: execs 199 and 200 re-ran looser shapes and the narrower one returned on-topic work. PMID 18002971: the barrier list (stairs, curbs, doorways) is credited by its abstract to stakeholder and clinician consultants, not the focus group; focus-group participants are credited with suggestions for simpler interaction.', "updated_at" = '2026-11-06 03:07' WHERE "exec_id" = 198;

