INSERT INTO "source_scans" ("scan_id", "ref_id", "mode", "catalogue_version", "target_parameter_id", "text_scope", "pages_read", "pages_total", "file_sha256", "open_pass_done", "method", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (8, 'REF-00992', 'catalogue', 12, NULL, 'full', 74, 74, '6599e260283e450ef734927c308171e73904d0952664c3f9f2cfdfe2c48e3bbf', 0, 'pre-screen', 'Second reading after the adversarial pass; where it differs it replaces the notes of the first scan of this source in this session. The first keyword search missed figures stated in other spellings (2.1m, 1.5m). Re-read pages 18, 19, 21, 26 and 35 in full. Found and filed: paras 1.11, 1.13(a), 1.26(e) widths (parameter 4) and the 2.1 m free height in 1.13(a) (parameter 11). Parameter 5: paras 2.7(d) (1500 x 1500 mm level landing before an entrance) and 3.28(a) (1500 x 1500 mm manoeuvring space before a lifting device) state a 1500 mm square, but the text calls them a landing and a manoeuvring space and does not call either a turning space, so they are not filed on parameter 5 (space for 360 degree rotation). Parameter 11: the word headroom does not occur; paras 1.38-1.39 refer overhead hazards to Approved Document K and state no figure, and the first scan''s gloss of them as the headroom reference was the reader''s. Parameters 7 and 10: no value found. Still not read end to end; diagrams are images and unread.', '2026-11-06 03:07', 'session_2026-11-06-pipeline-batch', '2026-11-06 03:07', 'session_2026-11-06-pipeline-batch');
INSERT INTO "source_scans" ("scan_id", "ref_id", "mode", "catalogue_version", "target_parameter_id", "text_scope", "pages_read", "pages_total", "file_sha256", "open_pass_done", "method", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (9, 'REF-00987', 'catalogue', 12, NULL, 'full', NULL, NULL, 'a2f0dc7adef43a4ace25e5f2792b7ab83a828e56d101f2ed84cbd40c77727554', 0, 'pre-screen', 'Second reading after the adversarial pass; where it differs it replaces the first scan''s notes. Correction: the first note said the only contrast provisions located were 504.4 and 703.5.1, neither for a surface pair. The word contrast occurs 22 times; 705.1.3 requires detectable warning surfaces to contrast visually with adjacent walking surfaces, which is a surface pair, but it states no light reflectance value or numeric difference, so no parameter 8 row is owed. Added: 405.5 ramp clear width (parameter 4). Passing spaces (403.5.3) are a different quantity and are not filed. Not read end to end; figures are images and unread.', '2026-11-06 03:07', 'session_2026-11-06-pipeline-batch', '2026-11-06 03:07', 'session_2026-11-06-pipeline-batch');

