INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id", "surfaced_in", "surfaced_quote", "updated_at", "updated_by_session") VALUES (154, 200, NULL, NULL, 'PENDING-VERIFICATION', 'Paquet, Joseph and D''Souza 2012, Computer re-sampling for demographically representative user populations in anthropometry: a case of doorway and clear floor space widths (Work)', 'https://pubmed.ncbi.nlm.nih.gov/22317349/', NULL, 3, 0, NULL, 'HYPOTHESIS from the abstract only (DOI 10.3233/WOR-2012-0703-4098): a sampling-method paper that uses door width and clear floor space width as its worked example. The abstract states no width figure; whether it reports a door width a person needs is unknown until the full text is read.', 'session_2026-11-06-pipeline-batch', '2026-11-06 03:07', NULL, 'retrieval-log/session_2026-11-06-pipeline-batch/a279045963e3ce02.json', '22317349', '2026-11-06 03:07', 'session_2026-11-06-pipeline-batch');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id", "surfaced_in", "surfaced_quote", "updated_at", "updated_by_session") VALUES (155, 200, NULL, NULL, 'PENDING-VERIFICATION', 'Savelsbergh, Douwes Dekker, Vermeer and Hopkins 1998, Locomoting through apertures of different width: a study of children with cerebral palsy (Pediatr Rehabil)', 'https://pubmed.ncbi.nlm.nih.gov/9661706/', NULL, 3, 0, NULL, 'HYPOTHESIS from the abstract only (DOI 10.3109/17518429809078610): 55 children, 23 non-handicapped and 32 with cerebral palsy (12 walking, 20 in wheelchairs), judged and attempted passage through apertures of varying width. Children, so a PROXY for the adults a door width serves (R13).', 'session_2026-11-06-pipeline-batch', '2026-11-06 03:07', NULL, 'retrieval-log/session_2026-11-06-pipeline-batch/a279045963e3ce02.json', '9661706', '2026-11-06 03:07', 'session_2026-11-06-pipeline-batch');
UPDATE "search_candidates" SET "notes" = 'HYPOTHESIS from the abstract only (DOI 10.1016/j.apmr.2010.01.009): measured the minimum passageway widths of 223 users (109 manual, 100 power, 14 scooter) for L-turn, 360-degree turn in place and U-turn; reports that 10-100% of users could not manoeuvre in spaces meeting the US guideline. Full text not reached (Europe PMC: subscription only). The DOI is a RETIRED stash row (REF-00784); an admission cross-files to that id. It would anchor parameters 4 and 5 and test the 1525 mm figure against the population measured. || RESOLVED 2026-11-06 by session_2026-11-06-pipeline-batch: R15, re-described from the source: Corrected after the adversarial pass: tier guess 3, not 1 (the abstract''s own design term is case series; the stash row REF-00784 carries tier_claimed 3). The abstract reports that 10% to 100% of users could not manoeuvre in spaces meeting the US guideline; recorded as harm on exec 197. Still abstract-level; no source text read.', "updated_at" = '2026-11-06 03:07' WHERE "candidate_id" = 150;
UPDATE "search_candidates" SET "notes" = 'HYPOTHESIS from the abstract only (DOI 10.1080/10400430903520280): reviews wheeled-mobility anthropometry research from four countries against national standards and reports that US standards, based on 1970s research, need updating. Full text not reached. The DOI sits on two unrelated pre-reset stash rows (REF-00059 and REF-00192: the shuffled-DOI defect, GAP-008), so the cross-filing id is not settled; resolve before any admission. || RESOLVED 2026-11-06 by session_2026-11-06-pipeline-batch: R15, re-described from the source: Corrected: the fourth author is D''Souza (payload LastName D''Souza); the title field of this row reads D Souza, an apostrophe lost to shell quoting. A title cannot be amended by any writer, so the payload (edb5140e7b6d9611.xml) is the record.', "updated_at" = '2026-11-06 03:07' WHERE "candidate_id" = 151;
UPDATE "search_candidates" SET "notes" = 'HYPOTHESIS from the abstract only (DOI 10.3109/17483107.2010.549898): measured room areas for a three-point turn for two four-wheeled scooters; states the 1.5 m turning circle is the current standard for manual wheelchairs. Full text not reached. Scooter users, so a PROXY for the population the 1525 mm figure serves. The DOI is a RETIRED stash row (REF-00972). || RESOLVED 2026-11-06 by session_2026-11-06-pipeline-batch: R15, re-described from the source: Corrected: the abstract reports two scooter models driven by our expert driver until the manoeuvre failed: one driver, no disabled participants. There is no study population to grade, so the PROXY statement above is withdrawn. Tier guess 3, not 1 (a device capability test).', "updated_at" = '2026-11-06 03:07' WHERE "candidate_id" = 152;

